interaction.fixed_prefix:
struct NoUrl;
struct HasUrl;

struct RequestBuilder<S> {
    url: String,
    state: S,
}

impl RequestBuilder<NoUrl> {
    fn new() -> Self {
        RequestBuilder {
            url: String::new(),
            state: NoUrl,
        }
    }
    fn url(self, u: &str)
        -> RequestBuilder<HasUrl>
    {
        RequestBuilder {
            url: u.to_string(),
            state: HasUrl,
        }
    }
}

impl RequestBuilder<HasUrl> {
    fn header(mut self, k: &str, v: &str)
        -> Self
    {
        self.url.push_str(" ");
        self.url.push_str(k);
        self.url.push_str("=");
        self.url.push_str(v);
        self
    }
    fn send(self) -> String {
        format!("GET {}", self.url)
    }
}

fn fetch_site() -> String {
    RequestBuilder::new()

interaction.fixed_suffix:
}

fn main() {
    let res = fetch_site();
    assert_eq!(
        res,
        "GET https://rust.lang Auth=123"
    );
}
